class Solution {
public:
    int cutOffTree(vector<vector<int>>& forest) {
        int m = forest.size(), n = forest[0].size();
        vector<tuple<int, int, int>> trees;
        for (int r = 0; r < m; r++) {
            for (int c = 0; c < n; c++) {
                if (forest[r][c] > 1) trees.push_back({forest[r][c], r, c});
            }
        }
        sort(trees.begin(), trees.end());

        auto bfs = [&](int sr, int sc, int tr, int tc) {
            if (sr == tr && sc == tc) return 0;
            queue<pair<int, int>> q;
            q.push({sr, sc});
            vector<vector<int>> dist(m, vector<int>(n, -1));
            dist[sr][sc] = 0;
            int dirs[4][2] = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};
            while (!q.empty()) {
                auto [r, c] = q.front();
                q.pop();
                if (r == tr && c == tc) return dist[r][c];
                for (auto& dir : dirs) {
                    int nr = r + dir[0], nc = c + dir[1];
                    if (nr >= 0 && nr < m && nc >= 0 && nc < n && forest[nr][nc] != 0 && dist[nr][nc] == -1) {
                        dist[nr][nc] = dist[r][c] + 1;
                        q.push({nr, nc});
                    }
                }
            }
            return -1;
        };

        int totalSteps = 0, currR = 0, currC = 0;
        for (auto& [h, tr, tc] : trees) {
            int d = bfs(currR, currC, tr, tc);
            if (d == -1) return -1;
            totalSteps += d;
            currR = tr;
            currC = tc;
        }
        return totalSteps;
    }
};

class Solution {
    public int cutOffTree(List<List<Integer>> forest) {
        int m = forest.size(), n = forest.get(0).size();
        List<int[]> trees = new ArrayList<>();
        for (int r = 0; r < m; r++) {
            for (int c = 0; c < n; c++) {
                int h = forest.get(r).get(c);
                if (h > 1) trees.add(new int[]{h, r, c});
            }
        }
        trees.sort((a, b) -> Integer.compare(a[0], b[0]));

        int totalSteps = 0, currR = 0, currC = 0;
        int[][] dirs = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};
        for (int[] t : trees) {
            int tr = t[1], tc = t[2];
            int d = bfs(forest, currR, currC, tr, tc, m, n, dirs);
            if (d == -1) return -1;
            totalSteps += d;
            currR = tr;
            currC = tc;
        }
        return totalSteps;
    }

    private int bfs(List<List<Integer>> forest, int sr, int sc, int tr, int tc, int m, int n, int[][] dirs) {
        if (sr == tr && sc == tc) return 0;
        Queue<int[]> q = new LinkedList<>();
        q.offer(new int[]{sr, sc});
        boolean[][] visited = new boolean[m][n];
        visited[sr][sc] = true;
        int steps = 0;
        while (!q.isEmpty()) {
            int size = q.size();
            steps++;
            for (int i = 0; i < size; i++) {
                int[] curr = q.poll();
                for (int[] dir : dirs) {
                    int nr = curr[0] + dir[0], nc = curr[1] + dir[1];
                    if (nr >= 0 && nr < m && nc >= 0 && nc < n && forest.get(nr).get(nc) != 0 && !visited[nr][nc]) {
                        if (nr == tr && nc == tc) return steps;
                        visited[nr][nc] = true;
                        q.offer(new int[]{nr, nc});
                    }
                }
            }
        }
        return -1;
    }
}

var cutOffTree = function(forest) {
    const m = forest.length, n = forest[0].length;
    const trees = [];
    for (let r = 0; r < m; r++) {
        for (let c = 0; c < n; c++) {
            if (forest[r][c] > 1) trees.push([forest[r][c], r, c]);
        }
    }
    trees.sort((a, b) => a[0] - b[0]);

    function bfs(sr, sc, tr, tc) {
        if (sr === tr && sc === tc) return 0;
        const q = [[sr, sc, 0]];
        const visited = new Set([`${sr},${sc}`]);
        const dirs = [[1, 0], [-1, 0], [0, 1], [0, -1]];
        while (q.length > 0) {
            const [r, c, d] = q.shift();
            for (const [dr, dc] of dirs) {
                const nr = r + dr, nc = c + dc;
                if (nr >= 0 && nr < m && nc >= 0 && nc < n && forest[nr][nc] !== 0) {
                    const key = `${nr},${nc}`;
                    if (!visited.has(key)) {
                        if (nr === tr && nc === tc) return d + 1;
                        visited.add(key);
                        q.push([nr, nc, d + 1]);
                    }
                }
            }
        }
        return -1;
    }

    let totalSteps = 0, currR = 0, currC = 0;
    for (const [h, tr, tc] of trees) {
        const d = bfs(currR, currC, tr, tc);
        if (d === -1) return -1;
        totalSteps += d;
        currR = tr;
        currC = tc;
    }
    return totalSteps;
};
